 const fam=field('family_id','Familia',{options:[]}),edition=field('edition','Edición o versión',{max:80,value:p.edition||''}),eds=el('datalist');eds.id=invKey('eds');edition.setAttribute('list',eds.id);form.append(eds);
 field('sku','SKU',{max:40,value:p.sku||''});field('region','Región de activación',{max:60,value:p.region||'',hint:'Ej.: Latinoamérica, global.'});
 const paint=()=>{const b=centerTax.brands.find(x=>x.name.toLowerCase()===brand.value.trim().toLowerCase());fam.replaceChildren(new Option('Sin familia',''));for(const f of centerTax.families.filter(f=>String(f.category_id)===cat.value&&(!b||f.brand_id===b.id)))fam.add(new Option(f.name+' ('+f.brand+')',String(f.id)));
  if(p.family_id)fam.value=String(p.family_id);paintEd();};const paintEd=()=>{eds.replaceChildren();const f=centerTax.families.find(f=>String(f.id)===fam.value);for(const e of f?.editions||[])eds.append(new Option(e));};
 cat.addEventListener('change',paint);brand.addEventListener('input',paint);fam.addEventListener('change',paintEd);paint();
